window.GS_UNREAL_I18N = {
  it: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Torna al sito",
    "u.nav.download": "Scarica",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Il testo di un gioco Unreal non sta mai dove ti aspetti",
    "u.lead": "Sciolto sul disco, dentro il container IoStore, o nel <em>pak</em> affiancato. GameStringer li prova tutti e tre, poi scrive una patch che il motore monta davvero.",
    "u.where.h": "Tre posti, non uno",
    "u.where.p1": "Unreal tiene le stringhe traducibili in file <strong>.locres</strong>. Dove finiscano dipende da come lo studio ha impacchettato il gioco, e non c'è una regola sola: cambiano da titolo a titolo, a volte fra due giochi dello stesso studio.",
    "u.where.l1": "<strong>Sciolti sul disco</strong> — i giochi UE4 più semplici li lasciano in chiaro dentro <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Nel container IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — compressi con Oodle, tipico dei giochi UE5.",
    "u.where.l3": "<strong>Nel pak classico affiancato al container</strong> — i <code>.locres</code> non sono asset, quindi non sono obbligati a passare dalla conversione in Zen e spesso restano lì.",
    "u.where.misura": "<strong>Una misura reale.</strong> Su un gioco UE5 di collaudo il container da 674 MB conteneva 12.601 elementi e <strong>zero</strong> <code>.locres</code>; il pak da 638 MB accanto ne conteneva quattro, di cui quello del gioco con <strong>1.679 voci</strong> di dialoghi e interfaccia. Un programma che guardi solo nel container dichiara quel gioco «senza testo». Non lo è.",
    "u.mount.h": "Una patch che non si monta è una patch che non esiste",
    "u.mount.p1": "Su Unreal la traduzione si applica con un file di override che il motore carica per ultimo, sostituendo il testo originale senza toccare i file del gioco. Fin qui è noto.",
    "u.mount.p2": "Il punto che costa caro è un altro: sui giochi <strong>UE5 con IoStore</strong> un <code>_P.pak</code> da solo <strong>viene ignorato in silenzio</strong>. Nessun errore, nessun avviso: il file c'è, il programma dice «patch installata», e il gioco resta in lingua originale. Serve la <strong>tripletta</strong> — <code>_P.pak</code> più la coppia <code>_P.utoc</code> e <code>_P.ucas</code> — anche quando quella coppia è vuota.",
    "u.mount.p3": "GameStringer la genera da sé a ogni applicazione. È il tipo di dettaglio che non si scopre leggendo la documentazione, ma provando il gioco e vedendo che l'italiano non arriva.",
    "u.aes.h": "Archivi cifrati: la chiave la metti tu",
    "u.aes.p1": "Alcuni studi cifrano l'indice dei propri <code>.pak</code> per scoraggiare il datamining. GameStringer <strong>non ricava la chiave</strong> dal gioco né dai suoi eseguibili: sarebbe aggirare una misura di protezione, e la nostra <a href=\"dmca.html\">politica</a> dice che non lo facciamo.",
    "u.aes.p2": "Se la chiave ce l'hai, incollala e il programma la usa per leggere i file di localizzazione del gioco che hai installato — come fanno gli strumenti di modding standard. Accetta le due forme in circolazione, base64 o esadecimale, ed è conservata cifrata sul tuo computer. Nessuna chiave viene distribuita o condivisa da GameStringer.",
    "u.aes.p3": "Se non ce l'hai, quel gioco resta fuori portata. Preferiamo dirtelo che fingere un guasto.",
    "u.how.h": "Come si fa",
    "u.how.s1": "<strong>Apri il gioco nella libreria.</strong> GameStringer riconosce il motore e la versione da solo.",
    "u.how.s2": "<strong>Premi String it!</strong> Estrazione, traduzione e applicazione sono un solo gesto: non devi sapere dove sta il testo né quale formato abbia.",
    "u.how.s3": "<strong>Scegli il compromesso.</strong> Preset costo/qualità con il prezzo stimato prima di partire, e la memoria di traduzione riusa quello che hai già tradotto.",
    "u.how.s4": "<strong>Gioca.</strong> La patch si disinstalla con un clic e non modifica i file originali.",
    "u.supp.h": "Cosa gestisce",
    "u.supp.l1": "<code>.locres</code> in tutte le versioni del formato, sciolti o dentro gli archivi",
    "u.supp.l2": "Pak legacy (v3–v9) e moderni con indice path-hash (v10+), decompressione Oodle inclusa",
    "u.supp.l3": "Container IoStore <code>.utoc</code> / <code>.ucas</code> dei giochi UE5",
    "u.supp.l4": "Indici cifrati AES-256, con chiave fornita da te",
    "u.supp.l5": "Generazione della tripletta di montaggio e rimozione pulita della patch",
    "u.lim.h": "E cosa no",
    "u.lim.l1": "I dialoghi compilati dentro <strong>Blueprint</strong> o <code>.uasset</code> cotti restano in parte fuori portata: sono testo che non passa dal sistema di localizzazione del motore.",
    "u.lim.l2": "I giochi <strong>senza alcuna localizzazione</strong> — pubblicati in una lingua sola, con le stringhe scritte direttamente nel codice — non hanno un <code>.locres</code> da tradurre.",
    "u.lim.l3": "Gli archivi cifrati richiedono la chiave, che non forniamo noi.",
    "u.data.h": "Non fidarti di questa pagina",
    "u.data.p1": "Ogni motore ha titoli che funzionano e titoli che resistono, e nessuna pagina di presentazione lo racconta onestamente. Per questo la compatibilità la pubblichiamo <strong>misurata</strong>: gioco per gioco, quante volte è stato provato, fino a che punto è arrivato e com'è finita — dati veri dalle esecuzioni reali, non promesse.",
    "u.data.link": "Guarda la tabella di compatibilità →",
    "u.foot.dl": "Download",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Abbatti le barriere linguistiche dei videogiochi. Analizza, traduci, gioca."
  },
  en: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Back to site",
    "u.nav.download": "Download",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "The text in an Unreal game is never where you expect it",
    "u.lead": "Loose on disk, inside the IoStore container, or in the <em>pak</em> sitting next to it. GameStringer tries all three, then writes a patch the engine actually mounts.",
    "u.where.h": "Three places, not one",
    "u.where.p1": "Unreal keeps translatable strings in <strong>.locres</strong> files. Where they end up depends on how the studio packaged the game, and there is no single rule: it changes from title to title, sometimes between two games from the same studio.",
    "u.where.l1": "<strong>Loose on disk</strong> — simpler UE4 games leave them in the clear inside <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Inside the IoStore container</strong> (<code>.utoc</code> / <code>.ucas</code>) — Oodle-compressed, typical of UE5 games.",
    "u.where.l3": "<strong>In the legacy pak next to the container</strong> — <code>.locres</code> files are not assets, so they are not required to go through the Zen conversion and often stay there.",
    "u.where.misura": "<strong>A real measurement.</strong> On a UE5 test game the 674 MB container held 12,601 items and <strong>zero</strong> <code>.locres</code>; the 638 MB pak beside it held four, one of them the game's own with <strong>1,679 entries</strong> of dialogue and interface text. A program that only looks inside the container calls that game \"textless\". It is not.",
    "u.mount.h": "A patch that does not mount is a patch that does not exist",
    "u.mount.p1": "On Unreal a translation is applied through an override file the engine loads last, replacing the original text without touching the game's files. That much is well known.",
    "u.mount.p2": "The part that costs you is different: on <strong>UE5 games with IoStore</strong> a lone <code>_P.pak</code> is <strong>silently ignored</strong>. No error, no warning: the file is there, the program says \"patch installed\", and the game stays in its original language. You need the <strong>triplet</strong> — <code>_P.pak</code> plus the <code>_P.utoc</code> and <code>_P.ucas</code> pair — even when that pair is empty.",
    "u.mount.p3": "GameStringer generates it on every apply. It is the kind of detail you do not find in documentation, but by launching the game and seeing that the translation never arrives.",
    "u.aes.h": "Encrypted archives: you supply the key",
    "u.aes.p1": "Some studios encrypt their <code>.pak</code> index to discourage datamining. GameStringer <strong>does not recover the key</strong> from the game or its executables: that would be circumventing a protection measure, and our <a href=\"dmca.html\">policy</a> says we do not do it.",
    "u.aes.p2": "If you have the key, paste it and the program uses it to read the localization files of the game you own — the same way standard modding tools do. It takes either form in circulation, base64 or hex, and stores it encrypted on your machine. GameStringer never distributes or shares a key.",
    "u.aes.p3": "If you do not have it, that game stays out of reach. We would rather tell you than fake a malfunction.",
    "u.how.h": "How it works",
    "u.how.s1": "<strong>Open the game in your library.</strong> GameStringer identifies the engine and version on its own.",
    "u.how.s2": "<strong>Press String it!</strong> Extraction, translation and patching are a single gesture: you do not need to know where the text lives or what format it is in.",
    "u.how.s3": "<strong>Pick your trade-off.</strong> Cost/quality presets with the estimated price before you start, and a translation memory that reuses what you have already translated.",
    "u.how.s4": "<strong>Play.</strong> The patch uninstalls with one click and never modifies the original files.",
    "u.supp.h": "What it handles",
    "u.supp.l1": "<code>.locres</code> in every version of the format, loose or inside archives",
    "u.supp.l2": "Legacy paks (v3–v9) and modern path-hash indexes (v10+), Oodle decompression included",
    "u.supp.l3": "IoStore <code>.utoc</code> / <code>.ucas</code> containers from UE5 games",
    "u.supp.l4": "AES-256 encrypted indexes, with a key you provide",
    "u.supp.l5": "Generation of the mount triplet and clean removal of the patch",
    "u.lim.h": "And what it does not",
    "u.lim.l1": "Dialogue compiled into <strong>Blueprints</strong> or cooked <code>.uasset</code> files stays partly out of reach: it is text that never passes through the engine's localization system.",
    "u.lim.l2": "Games <strong>with no localization at all</strong> — shipped in a single language, with strings written straight into the code — have no <code>.locres</code> to translate.",
    "u.lim.l3": "Encrypted archives need the key, which we do not provide.",
    "u.data.h": "Do not trust this page",
    "u.data.p1": "Every engine has titles that work and titles that resist, and no marketing page tells you that honestly. So we publish compatibility <strong>measured</strong>: game by game, how many times it was attempted, how far it got and how it ended — real data from real runs, not promises.",
    "u.data.link": "See the compatibility table →",
    "u.foot.dl": "Download",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Break down the language barriers of video games. Analyze, translate, play."
  },
  es: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Volver al sitio",
    "u.nav.download": "Descargar",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "El texto de un juego Unreal nunca está donde lo esperas",
    "u.lead": "Suelto en el disco, dentro del contenedor IoStore o en el <em>pak</em> que lo acompaña. GameStringer prueba los tres y luego escribe un parche que el motor monta de verdad.",
    "u.where.h": "Tres sitios, no uno",
    "u.where.p1": "Unreal guarda las cadenas traducibles en archivos <strong>.locres</strong>. Dónde acaben depende de cómo empaquetó el juego el estudio, y no hay una regla única: cambia de un título a otro, a veces entre dos juegos del mismo estudio.",
    "u.where.l1": "<strong>Sueltos en el disco</strong> — los juegos UE4 más sencillos los dejan sin proteger dentro de <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Dentro del contenedor IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — comprimidos con Oodle, típico de los juegos UE5.",
    "u.where.l3": "<strong>En el pak clásico junto al contenedor</strong> — los <code>.locres</code> no son assets, así que no están obligados a pasar por la conversión a Zen y a menudo se quedan ahí.",
    "u.where.misura": "<strong>Una medición real.</strong> En un juego UE5 de prueba, el contenedor de 674 MB tenía 12.601 elementos y <strong>cero</strong> <code>.locres</code>; el pak de 638 MB que lo acompañaba tenía cuatro, uno de ellos el del propio juego con <strong>1.679 entradas</strong> de diálogo e interfaz. Un programa que solo mira dentro del contenedor declara ese juego «sin texto». No lo es.",
    "u.mount.h": "Un parche que no se monta es un parche que no existe",
    "u.mount.p1": "En Unreal la traducción se aplica con un archivo de sobreescritura que el motor carga en último lugar, sustituyendo el texto original sin tocar los archivos del juego. Hasta aquí es conocido.",
    "u.mount.p2": "Lo que cuesta caro es otra cosa: en los juegos <strong>UE5 con IoStore</strong> un <code>_P.pak</code> por sí solo <strong>se ignora en silencio</strong>. Sin error ni aviso: el archivo está, el programa dice «parche instalado» y el juego sigue en su idioma original. Hace falta el <strong>trío</strong> — <code>_P.pak</code> más la pareja <code>_P.utoc</code> y <code>_P.ucas</code> — incluso cuando esa pareja está vacía.",
    "u.mount.p3": "GameStringer lo genera solo en cada aplicación. Es el tipo de detalle que no se descubre leyendo la documentación, sino probando el juego y viendo que la traducción no llega.",
    "u.aes.h": "Archivos cifrados: la clave la pones tú",
    "u.aes.p1": "Algunos estudios cifran el índice de sus <code>.pak</code> para desalentar el datamining. GameStringer <strong>no obtiene la clave</strong> del juego ni de sus ejecutables: sería eludir una medida de protección, y nuestra <a href=\"dmca.html\">política</a> dice que no lo hacemos.",
    "u.aes.p2": "Si tienes la clave, pégala y el programa la usa para leer los archivos de localización del juego que tienes instalado, igual que las herramientas de modding estándar. Acepta las dos formas en circulación, base64 o hexadecimal, y se guarda cifrada en tu equipo. GameStringer no distribuye ni comparte ninguna clave.",
    "u.aes.p3": "Si no la tienes, ese juego queda fuera de alcance. Preferimos decírtelo antes que fingir una avería.",
    "u.how.h": "Cómo se hace",
    "u.how.s1": "<strong>Abre el juego en la biblioteca.</strong> GameStringer reconoce el motor y la versión por su cuenta.",
    "u.how.s2": "<strong>Pulsa String it!</strong> Extracción, traducción y aplicación son un solo gesto: no necesitas saber dónde está el texto ni en qué formato.",
    "u.how.s3": "<strong>Elige el compromiso.</strong> Ajustes de coste/calidad con el precio estimado antes de empezar, y una memoria de traducción que reutiliza lo ya traducido.",
    "u.how.s4": "<strong>Juega.</strong> El parche se desinstala con un clic y no modifica los archivos originales.",
    "u.supp.h": "Qué gestiona",
    "u.supp.l1": "<code>.locres</code> en todas las versiones del formato, sueltos o dentro de los archivos",
    "u.supp.l2": "Paks legacy (v3–v9) y modernos con índice path-hash (v10+), descompresión Oodle incluida",
    "u.supp.l3": "Contenedores IoStore <code>.utoc</code> / <code>.ucas</code> de los juegos UE5",
    "u.supp.l4": "Índices cifrados AES-256, con una clave que aportas tú",
    "u.supp.l5": "Generación del trío de montaje y eliminación limpia del parche",
    "u.lim.h": "Y qué no",
    "u.lim.l1": "Los diálogos compilados dentro de <strong>Blueprints</strong> o de <code>.uasset</code> cocinados quedan en parte fuera de alcance: es texto que no pasa por el sistema de localización del motor.",
    "u.lim.l2": "Los juegos <strong>sin ninguna localización</strong> — publicados en un solo idioma, con las cadenas escritas directamente en el código — no tienen un <code>.locres</code> que traducir.",
    "u.lim.l3": "Los archivos cifrados necesitan la clave, que no proporcionamos nosotros.",
    "u.data.h": "No te fíes de esta página",
    "u.data.p1": "Cada motor tiene títulos que funcionan y títulos que se resisten, y ninguna página de presentación lo cuenta con honestidad. Por eso publicamos la compatibilidad <strong>medida</strong>: juego por juego, cuántas veces se intentó, hasta dónde llegó y cómo acabó — datos reales de ejecuciones reales, no promesas.",
    "u.data.link": "Mira la tabla de compatibilidad →",
    "u.foot.dl": "Descarga",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Derriba las barreras lingüísticas de los videojuegos. Analiza, traduce, juega."
  },
  fr: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Retour au site",
    "u.nav.download": "Télécharger",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Le texte d'un jeu Unreal n'est jamais là où on l'attend",
    "u.lead": "En clair sur le disque, dans le conteneur IoStore, ou dans le <em>pak</em> posé à côté. GameStringer essaie les trois, puis écrit un patch que le moteur monte vraiment.",
    "u.where.h": "Trois endroits, pas un",
    "u.where.p1": "Unreal range les chaînes traduisibles dans des fichiers <strong>.locres</strong>. Où elles atterrissent dépend de la façon dont le studio a empaqueté le jeu, et il n'y a pas de règle unique : cela change d'un titre à l'autre, parfois entre deux jeux du même studio.",
    "u.where.l1": "<strong>En clair sur le disque</strong> — les jeux UE4 les plus simples les laissent tels quels dans <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Dans le conteneur IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — compressés en Oodle, typique des jeux UE5.",
    "u.where.l3": "<strong>Dans le pak classique à côté du conteneur</strong> — les <code>.locres</code> ne sont pas des assets, ils ne sont donc pas obligés de passer par la conversion Zen et y restent souvent.",
    "u.where.misura": "<strong>Une mesure réelle.</strong> Sur un jeu UE5 de test, le conteneur de 674 Mo contenait 12 601 éléments et <strong>zéro</strong> <code>.locres</code> ; le pak de 638 Mo à côté en contenait quatre, dont celui du jeu avec <strong>1 679 entrées</strong> de dialogues et d'interface. Un programme qui ne regarde que dans le conteneur déclare ce jeu « sans texte ». Il ne l'est pas.",
    "u.mount.h": "Un patch qui ne se monte pas est un patch qui n'existe pas",
    "u.mount.p1": "Sur Unreal, la traduction s'applique via un fichier de remplacement que le moteur charge en dernier, substituant le texte original sans toucher aux fichiers du jeu. Jusque-là, c'est connu.",
    "u.mount.p2": "Ce qui coûte cher est ailleurs : sur les jeux <strong>UE5 avec IoStore</strong>, un <code>_P.pak</code> seul est <strong>ignoré en silence</strong>. Aucune erreur, aucun avertissement : le fichier est là, le programme annonce « patch installé », et le jeu reste dans sa langue d'origine. Il faut le <strong>triplet</strong> — <code>_P.pak</code> plus la paire <code>_P.utoc</code> et <code>_P.ucas</code> — même quand cette paire est vide.",
    "u.mount.p3": "GameStringer le génère lui-même à chaque application. C'est le genre de détail qu'on ne trouve pas dans la documentation, mais en lançant le jeu et en constatant que la traduction n'arrive jamais.",
    "u.aes.h": "Archives chiffrées : la clé, c'est vous qui la fournissez",
    "u.aes.p1": "Certains studios chiffrent l'index de leurs <code>.pak</code> pour décourager le datamining. GameStringer <strong>ne récupère pas la clé</strong> depuis le jeu ni ses exécutables : ce serait contourner une mesure de protection, et notre <a href=\"dmca.html\">politique</a> dit que nous ne le faisons pas.",
    "u.aes.p2": "Si vous avez la clé, collez-la et le programme s'en sert pour lire les fichiers de localisation du jeu que vous possédez — comme le font les outils de modding standard. Il accepte les deux formes en circulation, base64 ou hexadécimal, et la conserve chiffrée sur votre machine. GameStringer ne distribue ni ne partage aucune clé.",
    "u.aes.p3": "Si vous ne l'avez pas, ce jeu reste hors de portée. Nous préférons vous le dire plutôt que simuler une panne.",
    "u.how.h": "Comment ça marche",
    "u.how.s1": "<strong>Ouvrez le jeu dans votre bibliothèque.</strong> GameStringer reconnaît le moteur et la version tout seul.",
    "u.how.s2": "<strong>Appuyez sur String it!</strong> Extraction, traduction et application ne font qu'un geste : vous n'avez pas à savoir où est le texte ni sous quel format.",
    "u.how.s3": "<strong>Choisissez le compromis.</strong> Préréglages coût/qualité avec le prix estimé avant de lancer, et une mémoire de traduction qui réutilise ce que vous avez déjà traduit.",
    "u.how.s4": "<strong>Jouez.</strong> Le patch se désinstalle en un clic et ne modifie jamais les fichiers d'origine.",
    "u.supp.h": "Ce qu'il gère",
    "u.supp.l1": "<code>.locres</code> dans toutes les versions du format, en clair ou dans les archives",
    "u.supp.l2": "Paks legacy (v3–v9) et modernes à index path-hash (v10+), décompression Oodle comprise",
    "u.supp.l3": "Conteneurs IoStore <code>.utoc</code> / <code>.ucas</code> des jeux UE5",
    "u.supp.l4": "Index chiffrés AES-256, avec une clé que vous fournissez",
    "u.supp.l5": "Génération du triplet de montage et suppression propre du patch",
    "u.lim.h": "Et ce qu'il ne gère pas",
    "u.lim.l1": "Les dialogues compilés dans des <strong>Blueprints</strong> ou des <code>.uasset</code> cuits restent en partie hors de portée : c'est du texte qui ne passe pas par le système de localisation du moteur.",
    "u.lim.l2": "Les jeux <strong>sans aucune localisation</strong> — publiés en une seule langue, avec les chaînes écrites directement dans le code — n'ont pas de <code>.locres</code> à traduire.",
    "u.lim.l3": "Les archives chiffrées demandent la clé, que nous ne fournissons pas.",
    "u.data.h": "Ne faites pas confiance à cette page",
    "u.data.p1": "Chaque moteur a des titres qui marchent et des titres qui résistent, et aucune page de présentation ne le raconte honnêtement. C'est pourquoi nous publions la compatibilité <strong>mesurée</strong> : jeu par jeu, combien de fois il a été tenté, jusqu'où il est allé et comment cela s'est terminé — des données réelles issues d'exécutions réelles, pas des promesses.",
    "u.data.link": "Voir le tableau de compatibilité →",
    "u.foot.dl": "Téléchargement",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Faites tomber les barrières linguistiques des jeux vidéo. Analysez, traduisez, jouez."
  },
  de: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Zurück zur Website",
    "u.nav.download": "Herunterladen",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Der Text eines Unreal-Spiels liegt nie dort, wo man ihn erwartet",
    "u.lead": "Offen auf der Festplatte, im IoStore-Container oder im <em>pak</em> daneben. GameStringer probiert alle drei und schreibt dann einen Patch, den die Engine wirklich einbindet.",
    "u.where.h": "Drei Orte, nicht einer",
    "u.where.p1": "Unreal hält übersetzbare Zeichenketten in <strong>.locres</strong>-Dateien. Wo sie landen, hängt davon ab, wie das Studio das Spiel gepackt hat, und es gibt keine einheitliche Regel: Es ändert sich von Titel zu Titel, manchmal zwischen zwei Spielen desselben Studios.",
    "u.where.l1": "<strong>Offen auf der Festplatte</strong> — einfachere UE4-Spiele lassen sie unverpackt in <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Im IoStore-Container</strong> (<code>.utoc</code> / <code>.ucas</code>) — Oodle-komprimiert, typisch für UE5-Spiele.",
    "u.where.l3": "<strong>Im klassischen Pak neben dem Container</strong> — <code>.locres</code>-Dateien sind keine Assets, müssen also nicht durch die Zen-Konvertierung und bleiben oft dort.",
    "u.where.misura": "<strong>Eine echte Messung.</strong> Bei einem UE5-Testspiel enthielt der 674-MB-Container 12.601 Elemente und <strong>null</strong> <code>.locres</code>; das 638-MB-Pak daneben enthielt vier, darunter das des Spiels mit <strong>1.679 Einträgen</strong> an Dialog- und Oberflächentext. Ein Programm, das nur in den Container schaut, erklärt dieses Spiel für „textlos\". Das ist es nicht.",
    "u.mount.h": "Ein Patch, der nicht eingebunden wird, ist kein Patch",
    "u.mount.p1": "Unter Unreal wird die Übersetzung über eine Override-Datei angewendet, die die Engine zuletzt lädt und die den Originaltext ersetzt, ohne die Spieldateien anzufassen. So weit ist das bekannt.",
    "u.mount.p2": "Teuer wird etwas anderes: Bei <strong>UE5-Spielen mit IoStore</strong> wird ein einzelnes <code>_P.pak</code> <strong>stillschweigend ignoriert</strong>. Kein Fehler, keine Warnung: Die Datei ist da, das Programm meldet „Patch installiert\", und das Spiel bleibt in der Originalsprache. Nötig ist das <strong>Trio</strong> — <code>_P.pak</code> plus das Paar <code>_P.utoc</code> und <code>_P.ucas</code> — auch wenn dieses Paar leer ist.",
    "u.mount.p3": "GameStringer erzeugt es bei jeder Anwendung selbst. Es ist die Art Detail, die man nicht in der Dokumentation findet, sondern indem man das Spiel startet und sieht, dass die Übersetzung nie ankommt.",
    "u.aes.h": "Verschlüsselte Archive: den Schlüssel lieferst du",
    "u.aes.p1": "Manche Studios verschlüsseln den Index ihrer <code>.pak</code>-Dateien, um Datamining zu erschweren. GameStringer <strong>ermittelt den Schlüssel nicht</strong> aus dem Spiel oder seinen ausführbaren Dateien: Das wäre das Umgehen einer Schutzmaßnahme, und unsere <a href=\"dmca.html\">Richtlinie</a> sagt, dass wir das nicht tun.",
    "u.aes.p2": "Wenn du den Schlüssel hast, füge ihn ein, und das Programm liest damit die Lokalisierungsdateien des Spiels, das du besitzt — genau wie gängige Modding-Werkzeuge. Es akzeptiert beide üblichen Formen, Base64 oder Hex, und speichert ihn verschlüsselt auf deinem Rechner. GameStringer verteilt oder teilt keine Schlüssel.",
    "u.aes.p3": "Ohne Schlüssel bleibt dieses Spiel außer Reichweite. Wir sagen es lieber, als einen Defekt vorzutäuschen.",
    "u.how.h": "So läuft es",
    "u.how.s1": "<strong>Öffne das Spiel in der Bibliothek.</strong> GameStringer erkennt Engine und Version von selbst.",
    "u.how.s2": "<strong>Drücke String it!</strong> Auslesen, Übersetzen und Anwenden sind ein einziger Handgriff: Du musst nicht wissen, wo der Text liegt oder welches Format er hat.",
    "u.how.s3": "<strong>Wähle den Kompromiss.</strong> Kosten-/Qualitätsvorgaben mit geschätztem Preis vor dem Start, und ein Übersetzungsspeicher, der bereits Übersetztes wiederverwendet.",
    "u.how.s4": "<strong>Spiele.</strong> Der Patch lässt sich mit einem Klick entfernen und verändert die Originaldateien nie.",
    "u.supp.h": "Was es beherrscht",
    "u.supp.l1": "<code>.locres</code> in allen Versionen des Formats, offen oder in Archiven",
    "u.supp.l2": "Legacy-Paks (v3–v9) und moderne Path-Hash-Indizes (v10+), Oodle-Dekompression inklusive",
    "u.supp.l3": "IoStore-Container <code>.utoc</code> / <code>.ucas</code> von UE5-Spielen",
    "u.supp.l4": "AES-256-verschlüsselte Indizes, mit einem Schlüssel von dir",
    "u.supp.l5": "Erzeugung des Einbinde-Trios und sauberes Entfernen des Patches",
    "u.lim.h": "Und was nicht",
    "u.lim.l1": "In <strong>Blueprints</strong> oder gekochte <code>.uasset</code>-Dateien einkompilierte Dialoge bleiben teilweise außer Reichweite: Dieser Text läuft nie durch das Lokalisierungssystem der Engine.",
    "u.lim.l2": "Spiele <strong>ganz ohne Lokalisierung</strong> — in nur einer Sprache veröffentlicht, mit direkt im Code stehenden Zeichenketten — haben keine <code>.locres</code> zum Übersetzen.",
    "u.lim.l3": "Verschlüsselte Archive brauchen den Schlüssel, den wir nicht liefern.",
    "u.data.h": "Trau dieser Seite nicht",
    "u.data.p1": "Jede Engine hat Titel, die funktionieren, und Titel, die sich sperren, und keine Produktseite erzählt das ehrlich. Deshalb veröffentlichen wir Kompatibilität <strong>gemessen</strong>: Spiel für Spiel, wie oft es versucht wurde, wie weit es kam und wie es ausging — echte Daten aus echten Durchläufen, keine Versprechen.",
    "u.data.link": "Zur Kompatibilitätstabelle →",
    "u.foot.dl": "Download",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Reiße die Sprachbarrieren von Videospielen ein. Analysieren, übersetzen, spielen."
  },
  pt: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Voltar ao site",
    "u.nav.download": "Baixar",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "O texto de um jogo Unreal nunca está onde você espera",
    "u.lead": "Solto no disco, dentro do contêiner IoStore ou no <em>pak</em> ao lado. O GameStringer tenta os três e depois escreve um patch que o motor realmente monta.",
    "u.where.h": "Três lugares, não um",
    "u.where.p1": "A Unreal guarda as cadeias traduzíveis em ficheiros <strong>.locres</strong>. Onde acabam depende de como o estúdio empacotou o jogo, e não há uma regra única: muda de título para título, às vezes entre dois jogos do mesmo estúdio.",
    "u.where.l1": "<strong>Soltos no disco</strong> — os jogos UE4 mais simples deixam-nos abertos em <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Dentro do contêiner IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — comprimidos com Oodle, típico dos jogos UE5.",
    "u.where.l3": "<strong>No pak clássico ao lado do contêiner</strong> — os <code>.locres</code> não são assets, portanto não precisam passar pela conversão Zen e muitas vezes ficam ali.",
    "u.where.misura": "<strong>Uma medição real.</strong> Num jogo UE5 de teste, o contêiner de 674 MB tinha 12.601 elementos e <strong>zero</strong> <code>.locres</code>; o pak de 638 MB ao lado tinha quatro, um deles o do próprio jogo com <strong>1.679 entradas</strong> de diálogo e interface. Um programa que só olha dentro do contêiner declara esse jogo «sem texto». Não é.",
    "u.mount.h": "Um patch que não monta é um patch que não existe",
    "u.mount.p1": "Na Unreal a tradução aplica-se com um ficheiro de substituição que o motor carrega por último, trocando o texto original sem tocar nos ficheiros do jogo. Até aqui é conhecido.",
    "u.mount.p2": "O que custa caro é outra coisa: nos jogos <strong>UE5 com IoStore</strong> um <code>_P.pak</code> sozinho é <strong>ignorado em silêncio</strong>. Sem erro, sem aviso: o ficheiro está lá, o programa diz «patch instalado» e o jogo continua no idioma original. É preciso o <strong>trio</strong> — <code>_P.pak</code> mais o par <code>_P.utoc</code> e <code>_P.ucas</code> — mesmo quando esse par está vazio.",
    "u.mount.p3": "O GameStringer gera-o sozinho a cada aplicação. É o tipo de detalhe que não se descobre lendo a documentação, mas abrindo o jogo e vendo que a tradução nunca chega.",
    "u.aes.h": "Arquivos cifrados: a chave é você que dá",
    "u.aes.p1": "Alguns estúdios cifram o índice dos seus <code>.pak</code> para desencorajar o datamining. O GameStringer <strong>não obtém a chave</strong> do jogo nem dos seus executáveis: seria contornar uma medida de proteção, e a nossa <a href=\"dmca.html\">política</a> diz que não fazemos isso.",
    "u.aes.p2": "Se tiver a chave, cole-a e o programa usa-a para ler os ficheiros de localização do jogo que tem instalado — como fazem as ferramentas de modding padrão. Aceita as duas formas em circulação, base64 ou hexadecimal, e guarda-a cifrada no seu computador. O GameStringer não distribui nem partilha nenhuma chave.",
    "u.aes.p3": "Se não a tiver, esse jogo fica fora de alcance. Preferimos dizer-lho a fingir uma avaria.",
    "u.how.h": "Como se faz",
    "u.how.s1": "<strong>Abra o jogo na biblioteca.</strong> O GameStringer reconhece o motor e a versão sozinho.",
    "u.how.s2": "<strong>Carregue em String it!</strong> Extração, tradução e aplicação são um só gesto: não precisa de saber onde está o texto nem em que formato.",
    "u.how.s3": "<strong>Escolha o compromisso.</strong> Predefinições de custo/qualidade com o preço estimado antes de começar, e uma memória de tradução que reutiliza o que já traduziu.",
    "u.how.s4": "<strong>Jogue.</strong> O patch desinstala-se com um clique e nunca altera os ficheiros originais.",
    "u.supp.h": "O que trata",
    "u.supp.l1": "<code>.locres</code> em todas as versões do formato, soltos ou dentro dos arquivos",
    "u.supp.l2": "Paks legacy (v3–v9) e modernos com índice path-hash (v10+), descompressão Oodle incluída",
    "u.supp.l3": "Contêineres IoStore <code>.utoc</code> / <code>.ucas</code> dos jogos UE5",
    "u.supp.l4": "Índices cifrados AES-256, com uma chave fornecida por si",
    "u.supp.l5": "Geração do trio de montagem e remoção limpa do patch",
    "u.lim.h": "E o que não",
    "u.lim.l1": "Os diálogos compilados dentro de <strong>Blueprints</strong> ou de <code>.uasset</code> cozinhados ficam em parte fora de alcance: é texto que não passa pelo sistema de localização do motor.",
    "u.lim.l2": "Os jogos <strong>sem qualquer localização</strong> — publicados numa só língua, com as cadeias escritas diretamente no código — não têm um <code>.locres</code> para traduzir.",
    "u.lim.l3": "Os arquivos cifrados precisam da chave, que não fornecemos.",
    "u.data.h": "Não confie nesta página",
    "u.data.p1": "Cada motor tem títulos que funcionam e títulos que resistem, e nenhuma página de apresentação conta isso com honestidade. Por isso publicamos a compatibilidade <strong>medida</strong>: jogo a jogo, quantas vezes foi tentado, até onde chegou e como acabou — dados reais de execuções reais, não promessas.",
    "u.data.link": "Ver a tabela de compatibilidade →",
    "u.foot.dl": "Download",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Derrube as barreiras linguísticas dos videogames. Analise, traduza, jogue."
  },
  pl: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Powrót do strony",
    "u.nav.download": "Pobierz",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Tekst gry na Unrealu nigdy nie leży tam, gdzie się go spodziewasz",
    "u.lead": "Luzem na dysku, w kontenerze IoStore albo w <em>paku</em> obok. GameStringer sprawdza wszystkie trzy miejsca, a potem tworzy łatkę, którą silnik naprawdę wczytuje.",
    "u.where.h": "Trzy miejsca, nie jedno",
    "u.where.p1": "Unreal trzyma teksty do tłumaczenia w plikach <strong>.locres</strong>. To, gdzie trafią, zależy od tego, jak studio spakowało grę, i nie ma jednej reguły: zmienia się z tytułu na tytuł, czasem między dwiema grami tego samego studia.",
    "u.where.l1": "<strong>Luzem na dysku</strong> — prostsze gry UE4 zostawiają je otwarte w <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>W kontenerze IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — skompresowane Oodle, typowe dla gier UE5.",
    "u.where.l3": "<strong>W klasycznym paku obok kontenera</strong> — pliki <code>.locres</code> nie są assetami, więc nie muszą przechodzić przez konwersję Zen i często tam zostają.",
    "u.where.misura": "<strong>Prawdziwy pomiar.</strong> W testowej grze UE5 kontener o rozmiarze 674 MB zawierał 12 601 elementów i <strong>zero</strong> plików <code>.locres</code>; pak 638 MB obok zawierał cztery, w tym plik samej gry z <strong>1679 wpisami</strong> dialogów i interfejsu. Program, który zagląda tylko do kontenera, uznaje tę grę za „pozbawioną tekstu\". Nie jest.",
    "u.mount.h": "Łatka, która się nie wczytuje, to łatka, której nie ma",
    "u.mount.p1": "W Unrealu tłumaczenie stosuje się przez plik nadpisujący, który silnik wczytuje na końcu, zastępując oryginalny tekst bez ruszania plików gry. Tyle jest znane.",
    "u.mount.p2": "Kosztowne jest co innego: w grach <strong>UE5 z IoStore</strong> sam <code>_P.pak</code> jest <strong>po cichu ignorowany</strong>. Żadnego błędu, żadnego ostrzeżenia: plik jest, program mówi „łatka zainstalowana\", a gra zostaje w oryginalnym języku. Potrzebna jest <strong>trójka</strong> — <code>_P.pak</code> plus para <code>_P.utoc</code> i <code>_P.ucas</code> — nawet gdy ta para jest pusta.",
    "u.mount.p3": "GameStringer tworzy ją sam przy każdym zastosowaniu. To rodzaj szczegółu, którego nie znajdziesz w dokumentacji, tylko uruchamiając grę i widząc, że tłumaczenie nie dociera.",
    "u.aes.h": "Zaszyfrowane archiwa: klucz podajesz ty",
    "u.aes.p1": "Niektóre studia szyfrują indeks swoich plików <code>.pak</code>, by utrudnić datamining. GameStringer <strong>nie odzyskuje klucza</strong> z gry ani z jej plików wykonywalnych: to byłoby obejście zabezpieczenia, a nasza <a href=\"dmca.html\">polityka</a> mówi, że tego nie robimy.",
    "u.aes.p2": "Jeśli masz klucz, wklej go, a program użyje go do odczytania plików lokalizacji gry, którą masz zainstalowaną — tak jak standardowe narzędzia moderskie. Przyjmuje obie krążące formy, base64 lub szesnastkową, i przechowuje go zaszyfrowany na twoim komputerze. GameStringer nie rozpowszechnia ani nie udostępnia żadnych kluczy.",
    "u.aes.p3": "Jeśli klucza nie masz, ta gra pozostaje poza zasięgiem. Wolimy to powiedzieć, niż udawać awarię.",
    "u.how.h": "Jak to działa",
    "u.how.s1": "<strong>Otwórz grę w bibliotece.</strong> GameStringer sam rozpoznaje silnik i wersję.",
    "u.how.s2": "<strong>Naciśnij String it!</strong> Wydobycie, tłumaczenie i zastosowanie to jeden gest: nie musisz wiedzieć, gdzie jest tekst ani w jakim jest formacie.",
    "u.how.s3": "<strong>Wybierz kompromis.</strong> Ustawienia koszt/jakość z szacowaną ceną przed startem i pamięć tłumaczeń, która wykorzystuje to, co już przetłumaczyłeś.",
    "u.how.s4": "<strong>Graj.</strong> Łatkę odinstalowuje się jednym kliknięciem i nigdy nie zmienia oryginalnych plików.",
    "u.supp.h": "Co obsługuje",
    "u.supp.l1": "<code>.locres</code> we wszystkich wersjach formatu, luzem lub w archiwach",
    "u.supp.l2": "Paki legacy (v3–v9) i nowoczesne z indeksem path-hash (v10+), wraz z dekompresją Oodle",
    "u.supp.l3": "Kontenery IoStore <code>.utoc</code> / <code>.ucas</code> gier UE5",
    "u.supp.l4": "Indeksy szyfrowane AES-256, z kluczem podanym przez ciebie",
    "u.supp.l5": "Generowanie trójki montującej i czyste usuwanie łatki",
    "u.lim.h": "A czego nie",
    "u.lim.l1": "Dialogi wkompilowane w <strong>Blueprinty</strong> lub w ugotowane pliki <code>.uasset</code> pozostają częściowo poza zasięgiem: to tekst, który nie przechodzi przez system lokalizacji silnika.",
    "u.lim.l2": "Gry <strong>bez żadnej lokalizacji</strong> — wydane w jednym języku, z tekstami wpisanymi wprost w kod — nie mają pliku <code>.locres</code> do przetłumaczenia.",
    "u.lim.l3": "Zaszyfrowane archiwa wymagają klucza, którego my nie dostarczamy.",
    "u.data.h": "Nie ufaj tej stronie",
    "u.data.p1": "Każdy silnik ma tytuły, które działają, i tytuły, które stawiają opór, a żadna strona produktowa nie mówi o tym uczciwie. Dlatego publikujemy zgodność <strong>zmierzoną</strong>: gra po grze, ile razy próbowano, jak daleko doszło i jak się skończyło — prawdziwe dane z prawdziwych uruchomień, nie obietnice.",
    "u.data.link": "Zobacz tabelę zgodności →",
    "u.foot.dl": "Pobieranie",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Przełam bariery językowe gier wideo. Analizuj, tłumacz, graj."
  },
  ru: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Назад на сайт",
    "u.nav.download": "Скачать",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Текст игры на Unreal никогда не лежит там, где его ждёшь",
    "u.lead": "Отдельными файлами на диске, внутри контейнера IoStore или в <em>pak</em> рядом с ним. GameStringer проверяет все три места, а затем создаёт патч, который движок действительно подключает.",
    "u.where.h": "Три места, а не одно",
    "u.where.p1": "Unreal хранит переводимые строки в файлах <strong>.locres</strong>. Где они окажутся, зависит от того, как студия упаковала игру, и единого правила нет: всё меняется от проекта к проекту, иногда между двумя играми одной студии.",
    "u.where.l1": "<strong>Отдельными файлами на диске</strong> — более простые игры на UE4 оставляют их открытыми в <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Внутри контейнера IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — сжатые Oodle, типично для игр на UE5.",
    "u.where.l3": "<strong>В классическом pak рядом с контейнером</strong> — файлы <code>.locres</code> не являются ассетами, поэтому не обязаны проходить конвертацию в Zen и часто остаются там.",
    "u.where.misura": "<strong>Реальное измерение.</strong> В тестовой игре на UE5 контейнер объёмом 674 МБ содержал 12 601 элемент и <strong>ноль</strong> файлов <code>.locres</code>; pak на 638 МБ рядом содержал четыре, включая файл самой игры с <strong>1679 записями</strong> диалогов и интерфейса. Программа, которая смотрит только в контейнер, объявляет такую игру «без текста». Это не так.",
    "u.mount.h": "Патч, который не подключается, — это патч, которого нет",
    "u.mount.p1": "В Unreal перевод применяется через файл переопределения, который движок загружает последним, заменяя исходный текст и не трогая файлы игры. До этого места всё известно.",
    "u.mount.p2": "Дорого обходится другое: в играх <strong>UE5 с IoStore</strong> одиночный <code>_P.pak</code> <strong>молча игнорируется</strong>. Ни ошибки, ни предупреждения: файл на месте, программа сообщает «патч установлен», а игра остаётся на языке оригинала. Нужна <strong>тройка</strong> — <code>_P.pak</code> плюс пара <code>_P.utoc</code> и <code>_P.ucas</code> — даже когда эта пара пустая.",
    "u.mount.p3": "GameStringer создаёт её сам при каждом применении. Такие детали не находят в документации — их находят, запустив игру и увидев, что перевод так и не появился.",
    "u.aes.h": "Зашифрованные архивы: ключ даёте вы",
    "u.aes.p1": "Некоторые студии шифруют индекс своих <code>.pak</code>, чтобы затруднить датамайнинг. GameStringer <strong>не извлекает ключ</strong> из игры или её исполняемых файлов: это было бы обходом технической защиты, а наша <a href=\"dmca.html\">политика</a> говорит, что мы так не делаем.",
    "u.aes.p2": "Если ключ у вас есть, вставьте его — и программа прочитает файлы локализации установленной у вас игры, так же как это делают стандартные инструменты моддинга. Принимаются обе распространённые формы, base64 или шестнадцатеричная, и ключ хранится зашифрованным на вашем компьютере. GameStringer не распространяет и не публикует ключи.",
    "u.aes.p3": "Если ключа нет, эта игра остаётся недоступной. Мы предпочитаем сказать об этом, а не изображать поломку.",
    "u.how.h": "Как это работает",
    "u.how.s1": "<strong>Откройте игру в библиотеке.</strong> GameStringer сам определит движок и версию.",
    "u.how.s2": "<strong>Нажмите String it!</strong> Извлечение, перевод и установка — одно действие: вам не нужно знать, где лежит текст и в каком он формате.",
    "u.how.s3": "<strong>Выберите компромисс.</strong> Пресеты «цена/качество» с оценкой стоимости до запуска и память переводов, которая использует уже переведённое.",
    "u.how.s4": "<strong>Играйте.</strong> Патч удаляется одним щелчком и никогда не изменяет исходные файлы.",
    "u.supp.h": "Что поддерживается",
    "u.supp.l1": "<code>.locres</code> во всех версиях формата, отдельно или внутри архивов",
    "u.supp.l2": "Старые pak (v3–v9) и современные с индексом path-hash (v10+), включая распаковку Oodle",
    "u.supp.l3": "Контейнеры IoStore <code>.utoc</code> / <code>.ucas</code> игр на UE5",
    "u.supp.l4": "Индексы, зашифрованные AES-256, с ключом от вас",
    "u.supp.l5": "Создание тройки для подключения и чистое удаление патча",
    "u.lim.h": "А что нет",
    "u.lim.l1": "Диалоги, вкомпилированные в <strong>Blueprint</strong> или в приготовленные <code>.uasset</code>, остаются частично недоступными: этот текст не проходит через систему локализации движка.",
    "u.lim.l2": "Игры <strong>вообще без локализации</strong> — выпущенные на одном языке, со строками, вписанными прямо в код, — не имеют <code>.locres</code> для перевода.",
    "u.lim.l3": "Зашифрованным архивам нужен ключ, который мы не предоставляем.",
    "u.data.h": "Не верьте этой странице",
    "u.data.p1": "У каждого движка есть игры, которые работают, и игры, которые сопротивляются, и ни одна презентационная страница не говорит об этом честно. Поэтому совместимость мы публикуем <strong>измеренной</strong>: игра за игрой, сколько раз пробовали, докуда дошло и чем закончилось — реальные данные реальных запусков, а не обещания.",
    "u.data.link": "Посмотреть таблицу совместимости →",
    "u.foot.dl": "Загрузка",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Сломайте языковые барьеры видеоигр. Анализируйте, переводите, играйте."
  },
  ja: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← サイトに戻る",
    "u.nav.download": "ダウンロード",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Unreal 製ゲームのテキストは、思った場所には決してない",
    "u.lead": "ディスク上にそのまま、IoStore コンテナの中、あるいは隣の <em>pak</em> の中。GameStringer は三か所すべてを試し、エンジンが本当に読み込むパッチを書きます。",
    "u.where.h": "一か所ではなく三か所",
    "u.where.p1": "Unreal は翻訳対象の文字列を <strong>.locres</strong> ファイルに保持します。どこに置かれるかはスタジオのパッケージ方法しだいで、統一された規則はありません。タイトルごとに変わり、同じスタジオの二作品でも違うことがあります。",
    "u.where.l1": "<strong>ディスク上にそのまま</strong> — 単純な UE4 のゲームは <code>Content/Localization/</code> にそのまま置いています。",
    "u.where.l2": "<strong>IoStore コンテナの中</strong>（<code>.utoc</code> / <code>.ucas</code>）— Oodle で圧縮されており、UE5 のゲームで一般的です。",
    "u.where.l3": "<strong>コンテナの隣にある従来の pak の中</strong> — <code>.locres</code> はアセットではないため Zen 変換を通る必要がなく、そのまま残ることが多いのです。",
    "u.where.misura": "<strong>実測値。</strong>検証に使った UE5 のゲームでは、674 MB のコンテナに 12,601 個の要素があり <code>.locres</code> は<strong>ゼロ</strong>。隣にあった 638 MB の pak には四つあり、そのうちゲーム本体のものには会話と UI の<strong>1,679 件</strong>が入っていました。コンテナしか見ないプログラムは、このゲームを「テキストなし」と判定します。実際は違います。",
    "u.mount.h": "読み込まれないパッチは、存在しないパッチ",
    "u.mount.p1": "Unreal では、エンジンが最後に読み込むオーバーライドファイルで翻訳を適用し、ゲームのファイルには触れずに原文を差し替えます。ここまでは知られた話です。",
    "u.mount.p2": "高くつくのは別の点です。<strong>IoStore を使う UE5 のゲーム</strong>では、<code>_P.pak</code> 単体は<strong>黙って無視されます</strong>。エラーも警告もなく、ファイルは存在し、プログラムは「パッチ導入済み」と表示し、ゲームは原語のまま。必要なのは<strong>三点セット</strong>— <code>_P.pak</code> に <code>_P.utoc</code> と <code>_P.ucas</code> の対を加えたもの — その対が空であっても必要です。",
    "u.mount.p3": "GameStringer は適用のたびに自分で生成します。ドキュメントを読んでも見つからず、ゲームを起動して翻訳が反映されないのを見て初めて分かる種類の細部です。",
    "u.aes.h": "暗号化アーカイブ：鍵はあなたが用意します",
    "u.aes.p1": "データマイニング対策として <code>.pak</code> の索引を暗号化しているスタジオがあります。GameStringer はゲーム本体や実行ファイルから<strong>鍵を割り出すことはしません</strong>。それは保護手段の回避にあたり、私たちの<a href=\"dmca.html\">方針</a>で行わないと定めているからです。",
    "u.aes.p2": "鍵をお持ちなら貼り付けてください。標準的な MOD ツールと同じように、お手元のゲームのローカライズファイルを読むのに使われます。流通している base64 と十六進の両形式に対応し、鍵はお使いのパソコンに暗号化して保存されます。GameStringer が鍵を配布・共有することはありません。",
    "u.aes.p3": "鍵がなければ、そのゲームは対象外のままです。故障のふりをするより、そう申し上げます。",
    "u.how.h": "使い方",
    "u.how.s1": "<strong>ライブラリでゲームを開きます。</strong>GameStringer がエンジンとバージョンを自動で判別します。",
    "u.how.s2": "<strong>String it! を押します。</strong>抽出・翻訳・適用はひとつの操作です。テキストの場所も形式も知る必要はありません。",
    "u.how.s3": "<strong>妥協点を選びます。</strong>開始前に概算費用が出るコスト／品質プリセットと、翻訳済みの内容を再利用する翻訳メモリ。",
    "u.how.s4": "<strong>遊びます。</strong>パッチはワンクリックで削除でき、元のファイルを変更することはありません。",
    "u.supp.h": "対応していること",
    "u.supp.l1": "全バージョンの <code>.locres</code>（単体でもアーカイブ内でも）",
    "u.supp.l2": "従来の pak（v3〜v9）と path-hash 索引の新形式（v10 以降）、Oodle 展開を含む",
    "u.supp.l3": "UE5 ゲームの IoStore コンテナ <code>.utoc</code> / <code>.ucas</code>",
    "u.supp.l4": "AES-256 で暗号化された索引（鍵はご自身で用意）",
    "u.supp.l5": "読み込み用三点セットの生成と、パッチのきれいな削除",
    "u.lim.h": "対応していないこと",
    "u.lim.l1": "<strong>Blueprint</strong> や cook 済み <code>.uasset</code> に埋め込まれた会話は一部届きません。エンジンのローカライズ機構を通らないテキストだからです。",
    "u.lim.l2": "<strong>ローカライズがまったくない</strong>ゲーム — 一言語のみで発売され、文字列がコードに直接書かれているもの — には翻訳すべき <code>.locres</code> がありません。",
    "u.lim.l3": "暗号化されたアーカイブには鍵が必要で、それは私たちが提供するものではありません。",
    "u.data.h": "このページを鵜呑みにしないでください",
    "u.data.p1": "どのエンジンにも、うまくいくタイトルと手強いタイトルがあります。それを正直に書く製品ページはありません。だから私たちは互換性を<strong>実測</strong>で公開しています。ゲームごとに、何回試され、どこまで進み、どう終わったか — 約束ではなく、実際の実行から得た本物のデータです。",
    "u.data.link": "互換性の一覧を見る →",
    "u.foot.dl": "ダウンロード",
    "u.foot.comm": "Community",
    "u.foot.tagline": "ビデオゲームの言語の壁を打ち破ろう。解析し、翻訳し、プレイする。"
  },
  zh: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← 返回网站",
    "u.nav.download": "下载",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "虚幻引擎游戏的文本，从来不在你以为的地方",
    "u.lead": "散落在硬盘上、藏在 IoStore 容器里，或者在旁边那个 <em>pak</em> 中。GameStringer 三处都会尝试，然后写出一个引擎真正会加载的补丁。",
    "u.where.h": "三个地方，不是一个",
    "u.where.p1": "虚幻引擎把可翻译的文本放在 <strong>.locres</strong> 文件里。它们最终落在哪里，取决于工作室如何打包游戏，并没有统一规则：不同作品各不相同，有时同一家工作室的两款游戏也不一样。",
    "u.where.l1": "<strong>散落在硬盘上</strong> — 较简单的 UE4 游戏直接放在 <code>Content/Localization/</code> 里。",
    "u.where.l2": "<strong>在 IoStore 容器里</strong>（<code>.utoc</code> / <code>.ucas</code>）— 用 Oodle 压缩，UE5 游戏的常见做法。",
    "u.where.l3": "<strong>在容器旁边的传统 pak 里</strong> — <code>.locres</code> 不是资产，因此不必经过 Zen 转换，常常就留在那里。",
    "u.where.misura": "<strong>一次真实测量。</strong>在一款用于验证的 UE5 游戏中，674 MB 的容器里有 12,601 个元素，<code>.locres</code> 为<strong>零</strong>；旁边 638 MB 的 pak 里却有四个，其中属于游戏本体的那个包含 <strong>1,679 条</strong>对白与界面文本。只看容器的程序会判定这款游戏「没有文本」。事实并非如此。",
    "u.mount.h": "加载不了的补丁，等于不存在的补丁",
    "u.mount.p1": "在虚幻引擎中，翻译通过一个覆盖文件生效：引擎最后加载它，替换原文而不改动游戏文件。这一点是常识。",
    "u.mount.p2": "真正代价高的是另一件事：在<strong>使用 IoStore 的 UE5 游戏</strong>中，单独的 <code>_P.pak</code> 会被<strong>悄无声息地忽略</strong>。没有报错，没有提示：文件在那里，程序显示「补丁已安装」，而游戏仍是原文。需要的是<strong>三件套</strong> — <code>_P.pak</code> 加上 <code>_P.utoc</code> 与 <code>_P.ucas</code> 这一对 — 即便这一对是空的。",
    "u.mount.p3": "GameStringer 每次应用时都会自行生成。这类细节读文档是找不到的，只有启动游戏、发现译文始终没出现，才会明白。",
    "u.aes.h": "加密档案：密钥由你提供",
    "u.aes.p1": "有些工作室会加密自己 <code>.pak</code> 的索引，以增加数据挖掘的难度。GameStringer <strong>不会从游戏或其可执行文件中还原密钥</strong>：那属于规避保护措施，我们的<a href=\"dmca.html\">政策</a>写明不这样做。",
    "u.aes.p2": "如果你有密钥，粘贴进来，程序就会用它读取你已安装游戏的本地化文件——和常见的模组工具一样。base64 和十六进制两种通行格式都支持，密钥会加密保存在你自己的电脑上。GameStringer 不会分发或分享任何密钥。",
    "u.aes.p3": "如果你没有密钥，那款游戏就仍在能力之外。我们宁愿直说，也不假装是故障。",
    "u.how.h": "怎么用",
    "u.how.s1": "<strong>在库中打开游戏。</strong>GameStringer 会自行识别引擎与版本。",
    "u.how.s2": "<strong>按下 String it!</strong> 提取、翻译、应用是同一个动作：你不需要知道文本在哪里，也不需要知道它是什么格式。",
    "u.how.s3": "<strong>选择取舍。</strong>成本／质量预设会在开始前给出预估价格，翻译记忆会复用你已经翻译过的内容。",
    "u.how.s4": "<strong>开始游戏。</strong>补丁一键卸载，且从不修改原始文件。",
    "u.supp.h": "支持什么",
    "u.supp.l1": "各版本格式的 <code>.locres</code>，无论散落在外还是在档案中",
    "u.supp.l2": "传统 pak（v3–v9）与采用 path-hash 索引的新版（v10+），含 Oodle 解压",
    "u.supp.l3": "UE5 游戏的 IoStore 容器 <code>.utoc</code> / <code>.ucas</code>",
    "u.supp.l4": "AES-256 加密的索引，密钥由你提供",
    "u.supp.l5": "生成加载所需的三件套，并可干净地移除补丁",
    "u.lim.h": "不支持什么",
    "u.lim.l1": "编译进 <strong>蓝图</strong> 或已烘焙 <code>.uasset</code> 的对白仍有部分够不到：这类文本不经过引擎的本地化系统。",
    "u.lim.l2": "<strong>完全没有本地化</strong>的游戏——只发行一种语言、文本直接写在代码里——没有可翻译的 <code>.locres</code>。",
    "u.lim.l3": "加密档案需要密钥，而密钥不由我们提供。",
    "u.data.h": "别轻信这个页面",
    "u.data.p1": "每种引擎都有能跑通的作品和顽固的作品，而没有哪个产品页会诚实地说这件事。所以我们把兼容性以<strong>实测</strong>的方式公开：逐款游戏，被尝试过多少次、走到哪一步、结果如何——来自真实运行的真实数据，不是承诺。",
    "u.data.link": "查看兼容性表 →",
    "u.foot.dl": "下载",
    "u.foot.comm": "Community",
    "u.foot.tagline": "打破电子游戏的语言壁垒。分析、翻译、畅玩。"
  },
  ko: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← 사이트로 돌아가기",
    "u.nav.download": "다운로드",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "언리얼 게임의 텍스트는 결코 예상한 곳에 있지 않습니다",
    "u.lead": "디스크에 그대로, IoStore 컨테이너 안에, 또는 그 옆의 <em>pak</em> 안에. GameStringer는 세 곳을 모두 확인한 뒤, 엔진이 실제로 불러오는 패치를 만듭니다.",
    "u.where.h": "한 곳이 아니라 세 곳",
    "u.where.p1": "언리얼은 번역 대상 문자열을 <strong>.locres</strong> 파일에 담습니다. 어디에 놓이는지는 스튜디오가 게임을 어떻게 패키징했는지에 달려 있고, 하나의 규칙은 없습니다. 작품마다 다르고, 같은 스튜디오의 두 게임 사이에서도 달라집니다.",
    "u.where.l1": "<strong>디스크에 그대로</strong> — 비교적 단순한 UE4 게임은 <code>Content/Localization/</code>에 그대로 둡니다.",
    "u.where.l2": "<strong>IoStore 컨테이너 안</strong>(<code>.utoc</code> / <code>.ucas</code>) — Oodle로 압축되며, UE5 게임에서 일반적입니다.",
    "u.where.l3": "<strong>컨테이너 옆의 기존 pak 안</strong> — <code>.locres</code>는 애셋이 아니므로 Zen 변환을 거칠 필요가 없고, 그대로 남는 경우가 많습니다.",
    "u.where.misura": "<strong>실제 측정값.</strong> 검증에 쓴 UE5 게임에서 674 MB 컨테이너에는 12,601개 요소가 있었지만 <code>.locres</code>는 <strong>하나도</strong> 없었습니다. 옆에 있던 638 MB pak에는 네 개가 있었고, 그중 게임 본체의 것에는 대사와 UI <strong>1,679개 항목</strong>이 들어 있었습니다. 컨테이너만 들여다보는 프로그램은 이 게임을 「텍스트 없음」으로 판정합니다. 사실이 아닙니다.",
    "u.mount.h": "로드되지 않는 패치는 없는 패치입니다",
    "u.mount.p1": "언리얼에서는 엔진이 마지막에 읽는 오버라이드 파일로 번역을 적용해, 게임 파일을 건드리지 않고 원문을 교체합니다. 여기까지는 알려진 이야기입니다.",
    "u.mount.p2": "비싼 대가를 치르는 지점은 다릅니다. <strong>IoStore를 쓰는 UE5 게임</strong>에서는 <code>_P.pak</code> 하나만으로는 <strong>조용히 무시됩니다</strong>. 오류도 경고도 없이 파일은 그대로 있고, 프로그램은 「패치 설치됨」이라 말하며, 게임은 원어 그대로입니다. 필요한 것은 <strong>세 짝</strong> — <code>_P.pak</code>에 <code>_P.utoc</code>와 <code>_P.ucas</code> 한 쌍을 더한 것 — 그 쌍이 비어 있어도 필요합니다.",
    "u.mount.p3": "GameStringer는 적용할 때마다 이를 직접 만듭니다. 문서를 읽어서는 알 수 없고, 게임을 실행해 번역이 끝내 나타나지 않는 것을 보고서야 알게 되는 종류의 세부 사항입니다.",
    "u.aes.h": "암호화된 아카이브: 키는 사용자가 제공합니다",
    "u.aes.p1": "일부 스튜디오는 데이터마이닝을 막기 위해 <code>.pak</code> 인덱스를 암호화합니다. GameStringer는 게임이나 실행 파일에서 <strong>키를 복원하지 않습니다</strong>. 그것은 보호 조치를 우회하는 일이며, 저희 <a href=\"dmca.html\">정책</a>에 하지 않는다고 명시되어 있습니다.",
    "u.aes.p2": "키가 있다면 붙여 넣으세요. 일반적인 모딩 도구와 마찬가지로, 보유하신 게임의 현지화 파일을 읽는 데 사용됩니다. 통용되는 base64와 16진수 두 형식을 모두 받으며, 키는 사용자의 컴퓨터에 암호화되어 저장됩니다. GameStringer는 어떤 키도 배포하거나 공유하지 않습니다.",
    "u.aes.p3": "키가 없다면 그 게임은 손이 닿지 않는 채로 남습니다. 고장인 척하기보다는 그렇게 말씀드리겠습니다.",
    "u.how.h": "사용 방법",
    "u.how.s1": "<strong>라이브러리에서 게임을 엽니다.</strong> GameStringer가 엔진과 버전을 스스로 인식합니다.",
    "u.how.s2": "<strong>String it!을 누릅니다.</strong> 추출·번역·적용이 한 번의 동작입니다. 텍스트가 어디에 있는지, 어떤 형식인지 알 필요가 없습니다.",
    "u.how.s3": "<strong>절충안을 고릅니다.</strong> 시작 전에 예상 비용을 보여 주는 비용/품질 프리셋과, 이미 번역한 내용을 재사용하는 번역 메모리.",
    "u.how.s4": "<strong>플레이합니다.</strong> 패치는 클릭 한 번으로 제거되며 원본 파일을 변경하지 않습니다.",
    "u.supp.h": "지원하는 것",
    "u.supp.l1": "모든 버전의 <code>.locres</code>, 낱개든 아카이브 안이든",
    "u.supp.l2": "기존 pak(v3–v9)과 path-hash 인덱스의 최신 pak(v10+), Oodle 압축 해제 포함",
    "u.supp.l3": "UE5 게임의 IoStore 컨테이너 <code>.utoc</code> / <code>.ucas</code>",
    "u.supp.l4": "AES-256으로 암호화된 인덱스, 키는 사용자가 제공",
    "u.supp.l5": "로드용 세 짝 생성과 패치의 깔끔한 제거",
    "u.lim.h": "지원하지 않는 것",
    "u.lim.l1": "<strong>블루프린트</strong>나 쿠킹된 <code>.uasset</code>에 컴파일된 대사는 일부 닿지 않습니다. 엔진의 현지화 시스템을 거치지 않는 텍스트이기 때문입니다.",
    "u.lim.l2": "<strong>현지화가 전혀 없는</strong> 게임 — 단일 언어로 출시되고 문자열이 코드에 직접 쓰인 경우 — 에는 번역할 <code>.locres</code>가 없습니다.",
    "u.lim.l3": "암호화된 아카이브에는 키가 필요하며, 그 키는 저희가 제공하지 않습니다.",
    "u.data.h": "이 페이지를 믿지 마세요",
    "u.data.p1": "어느 엔진에나 잘 되는 작품과 버티는 작품이 있지만, 이를 정직하게 말하는 제품 페이지는 없습니다. 그래서 저희는 호환성을 <strong>측정한 값</strong>으로 공개합니다. 게임별로 몇 번 시도되었는지, 어디까지 갔는지, 어떻게 끝났는지 — 약속이 아니라 실제 실행에서 나온 진짜 데이터입니다.",
    "u.data.link": "호환성 표 보기 →",
    "u.foot.dl": "다운로드",
    "u.foot.comm": "Community",
    "u.foot.tagline": "비디오 게임의 언어 장벽을 허무세요. 분석하고, 번역하고, 플레이하세요."
  },
  el: {
    "u.doc.title": "Unreal Engine — GameStringer",
    "u.nav.back": "← Επιστροφή στον ιστότοπο",
    "u.nav.download": "Λήψη",
    "u.pill": "Unreal Engine 4 · 5",
    "u.h1": "Το κείμενο ενός παιχνιδιού Unreal δεν βρίσκεται ποτέ εκεί που το περιμένεις",
    "u.lead": "Ελεύθερο στον δίσκο, μέσα στο κοντέινερ IoStore ή στο <em>pak</em> δίπλα του. Το GameStringer τα δοκιμάζει και τα τρία, και μετά γράφει ένα patch που η μηχανή φορτώνει πραγματικά.",
    "u.where.h": "Τρία σημεία, όχι ένα",
    "u.where.p1": "Η Unreal κρατά τα μεταφράσιμα κείμενα σε αρχεία <strong>.locres</strong>. Το πού καταλήγουν εξαρτάται από το πώς πακετάρισε το παιχνίδι το στούντιο, και δεν υπάρχει ενιαίος κανόνας: αλλάζει από τίτλο σε τίτλο, ενίοτε ανάμεσα σε δύο παιχνίδια του ίδιου στούντιο.",
    "u.where.l1": "<strong>Ελεύθερα στον δίσκο</strong> — τα απλούστερα παιχνίδια UE4 τα αφήνουν ανέγγιχτα μέσα στο <code>Content/Localization/</code>.",
    "u.where.l2": "<strong>Μέσα στο κοντέινερ IoStore</strong> (<code>.utoc</code> / <code>.ucas</code>) — συμπιεσμένα με Oodle, τυπικό στα παιχνίδια UE5.",
    "u.where.l3": "<strong>Στο κλασικό pak δίπλα στο κοντέινερ</strong> — τα <code>.locres</code> δεν είναι assets, οπότε δεν είναι υποχρεωμένα να περάσουν από τη μετατροπή σε Zen και συχνά μένουν εκεί.",
    "u.where.misura": "<strong>Μια πραγματική μέτρηση.</strong> Σε ένα δοκιμαστικό παιχνίδι UE5, το κοντέινερ των 674 MB περιείχε 12.601 στοιχεία και <strong>μηδέν</strong> <code>.locres</code>· το pak των 638 MB δίπλα περιείχε τέσσερα, ένα εκ των οποίων του ίδιου του παιχνιδιού με <strong>1.679 καταχωρίσεις</strong> διαλόγων και διεπαφής. Ένα πρόγραμμα που κοιτάζει μόνο μέσα στο κοντέινερ χαρακτηρίζει αυτό το παιχνίδι «χωρίς κείμενο». Δεν είναι.",
    "u.mount.h": "Ένα patch που δεν φορτώνεται είναι patch που δεν υπάρχει",
    "u.mount.p1": "Στην Unreal η μετάφραση εφαρμόζεται με ένα αρχείο override που η μηχανή φορτώνει τελευταίο, αντικαθιστώντας το πρωτότυπο κείμενο χωρίς να αγγίζει τα αρχεία του παιχνιδιού. Ως εδώ είναι γνωστό.",
    "u.mount.p2": "Το ακριβό είναι αλλού: στα παιχνίδια <strong>UE5 με IoStore</strong> ένα σκέτο <code>_P.pak</code> <strong>αγνοείται σιωπηλά</strong>. Κανένα σφάλμα, καμία προειδοποίηση: το αρχείο υπάρχει, το πρόγραμμα λέει «το patch εγκαταστάθηκε», και το παιχνίδι μένει στην αρχική γλώσσα. Χρειάζεται η <strong>τριάδα</strong> — <code>_P.pak</code> συν το ζεύγος <code>_P.utoc</code> και <code>_P.ucas</code> — ακόμη κι όταν το ζεύγος είναι άδειο.",
    "u.mount.p3": "Το GameStringer την παράγει μόνο του σε κάθε εφαρμογή. Είναι η λεπτομέρεια που δεν τη βρίσκεις διαβάζοντας τεκμηρίωση, αλλά ανοίγοντας το παιχνίδι και βλέποντας ότι η μετάφραση δεν φτάνει ποτέ.",
    "u.aes.h": "Κρυπτογραφημένα αρχεία: το κλειδί το δίνεις εσύ",
    "u.aes.p1": "Ορισμένα στούντιο κρυπτογραφούν το ευρετήριο των <code>.pak</code> τους για να αποθαρρύνουν το datamining. Το GameStringer <strong>δεν ανακτά το κλειδί</strong> από το παιχνίδι ή τα εκτελέσιμά του: αυτό θα ήταν παράκαμψη μέτρου προστασίας, και η <a href=\"dmca.html\">πολιτική</a> μας λέει ότι δεν το κάνουμε.",
    "u.aes.p2": "Αν έχεις το κλειδί, επικόλλησέ το και το πρόγραμμα το χρησιμοποιεί για να διαβάσει τα αρχεία τοπικοποίησης του παιχνιδιού που έχεις εγκαταστήσει — όπως κάνουν τα καθιερωμένα εργαλεία modding. Δέχεται και τις δύο μορφές που κυκλοφορούν, base64 ή δεκαεξαδική, και το φυλάει κρυπτογραφημένο στον υπολογιστή σου. Το GameStringer δεν διανέμει ούτε μοιράζεται κλειδιά.",
    "u.aes.p3": "Αν δεν το έχεις, εκείνο το παιχνίδι μένει εκτός εμβέλειας. Προτιμούμε να στο πούμε παρά να προσποιηθούμε βλάβη.",
    "u.how.h": "Πώς γίνεται",
    "u.how.s1": "<strong>Άνοιξε το παιχνίδι στη βιβλιοθήκη.</strong> Το GameStringer αναγνωρίζει μόνο του τη μηχανή και την έκδοση.",
    "u.how.s2": "<strong>Πάτα String it!</strong> Εξαγωγή, μετάφραση και εφαρμογή είναι μία κίνηση: δεν χρειάζεται να ξέρεις πού είναι το κείμενο ούτε σε τι μορφή.",
    "u.how.s3": "<strong>Διάλεξε τον συμβιβασμό.</strong> Προεπιλογές κόστους/ποιότητας με εκτιμώμενη τιμή πριν ξεκινήσεις, και μνήμη μεταφράσεων που ξαναχρησιμοποιεί όσα έχεις ήδη μεταφράσει.",
    "u.how.s4": "<strong>Παίξε.</strong> Το patch απεγκαθίσταται με ένα κλικ και δεν αλλάζει ποτέ τα πρωτότυπα αρχεία.",
    "u.supp.h": "Τι υποστηρίζει",
    "u.supp.l1": "<code>.locres</code> σε όλες τις εκδόσεις της μορφής, ελεύθερα ή μέσα σε αρχεία",
    "u.supp.l2": "Παλαιά pak (v3–v9) και σύγχρονα με ευρετήριο path-hash (v10+), με αποσυμπίεση Oodle",
    "u.supp.l3": "Κοντέινερ IoStore <code>.utoc</code> / <code>.ucas</code> των παιχνιδιών UE5",
    "u.supp.l4": "Κρυπτογραφημένα ευρετήρια AES-256, με κλειδί που δίνεις εσύ",
    "u.supp.l5": "Δημιουργία της τριάδας φόρτωσης και καθαρή αφαίρεση του patch",
    "u.lim.h": "Και τι όχι",
    "u.lim.l1": "Οι διάλογοι που έχουν μεταγλωττιστεί μέσα σε <strong>Blueprints</strong> ή σε ψημένα <code>.uasset</code> μένουν εν μέρει εκτός εμβέλειας: είναι κείμενο που δεν περνά από το σύστημα τοπικοποίησης της μηχανής.",
    "u.lim.l2": "Τα παιχνίδια <strong>χωρίς καμία τοπικοποίηση</strong> — που κυκλοφόρησαν σε μία μόνο γλώσσα, με τα κείμενα γραμμένα κατευθείαν στον κώδικα — δεν έχουν <code>.locres</code> να μεταφραστεί.",
    "u.lim.l3": "Τα κρυπτογραφημένα αρχεία χρειάζονται το κλειδί, το οποίο δεν το παρέχουμε εμείς.",
    "u.data.h": "Μην εμπιστεύεσαι αυτή τη σελίδα",
    "u.data.p1": "Κάθε μηχανή έχει τίτλους που δουλεύουν και τίτλους που αντιστέκονται, και καμία σελίδα προϊόντος δεν το λέει τίμια. Γι' αυτό δημοσιεύουμε τη συμβατότητα <strong>μετρημένη</strong>: παιχνίδι προς παιχνίδι, πόσες φορές δοκιμάστηκε, μέχρι πού έφτασε και πώς κατέληξε — πραγματικά δεδομένα από πραγματικές εκτελέσεις, όχι υποσχέσεις.",
    "u.data.link": "Δες τον πίνακα συμβατότητας →",
    "u.foot.dl": "Download",
    "u.foot.comm": "Community",
    "u.foot.tagline": "Γκρέμισε τα γλωσσικά εμπόδια των βιντεοπαιχνιδιών. Ανάλυσε, μετάφρασε, παίξε."
  }
};
